mapper.select:
SELECT id, main_title AS mainTitle, summary, topic_status AS topicStatus, confidence_score AS confidenceScore, platform_count AS platformCount, hotspot_count AS hotspotCount, related_platforms AS relatedPlatforms, first_seen_time AS firstSeenTime, last_seen_time AS lastSeenTime, created_at AS createdAt, updated_at AS updatedAt FROM cross_platform_topic WHERE topic_status = 'active'
AND FIND_IN_SET(#{platform}, related_platforms)
ORDER BY platform_count DESC, last_seen_time DESC, id DESC LIMIT #{limit}
